ATL_SRC.push(['@atl/billing.js', 0, `// Reads the weekly "Billing Activity" workbooks (Piper Warehouse Activity Details) into throughput numbers.
//
// Every file has an activity sheet: a title "… Activity Details 10/25/2026 thru 10/31/2026", a "Customer:" line,
// and a header row (row 3) starting "In/Out" over one row per load. Rules (set by Josh, Nov 2026):
//  - Column B (In/Out): In = inbound, Out = outbound.
//  - A line whose PO Number or Note says "Purge", "DNB" or "Do not Bill" is ignored.
//  - Skids customers — Maxxon, Electrolit, Nexus Circular (Units "Pallets"): throughput = skids in / skids out
//    (column K). Weight means nothing for them.
//  - Weight customers — ATL UPM, Smurfit Westrock, IPG, Catalyst, Catalyst Pulp and Paper Sales XDK, Domtar 6021
//    (Units with Tons + MT): skids are rolls, so throughput is by weight — the shipment weight (lbs) ÷ 2000 = tons,
//    ÷ 2204.62 = MT. The weight is found by its "Weight (lbs)" heading (column O in most files; Domtar has it in K),
//    falling back to column O.
//  - Nexus: the Note column (6021 / 6049) says which building each load went to.
//  - Inventory adjustment lines are counted like any other line (only Purge / DNB / Do not Bill are ignored).
//  - IPG is Tons + MT only for now. If a weight customer is ever given Pallets / Bundles again, those come from its
//    billing sheet's "Initial Storage per Pallet / Bundle" quantities (its skids are rolls), not the Skids column.
//  - Loads shipped / loads in (Monthly Inputs): each Out / In line is one load (counted once per BL #). Loads dated
//    in the month before the week ending's month (a week that starts in one month and ends in the next) count for
//    that month. Loads in are for display only.
import { excelDate, norm, num } from '@atl/util.js';
import { namesOf, unitsOf } from '@atl/throughput.js';

const SHEETJS = 'https://cdn.sheetjs.com/xlsx-0.20.3/package/xlsx.mjs';
const LBS_PER_TON = 2000, LBS_PER_MT = 2204.62;
const NOT_THROUGHPUT = /\\bpurge\\b|\\bdnb\\b|do\\s*not\\s*bill/i;
const COL_O = 14; // column O (A = 0)
const txt = v => String(v ?? '').trim();
const key = v => norm(v).replace(/[^A-Z0-9]/g, '');

/** "10/25/2026 thru 10/31/2026" → '2026-10-31' */
function weekFromTitle(rows) {
  for (const r of rows.slice(0, 6)) for (const c of r) {
    const m = txt(c).match(/thru\\s+(\\d{1,2})\\/(\\d{1,2})\\/(\\d{2,4})/i);
    if (m) { const y = m[3].length === 2 ? '20' + m[3] : m[3]; return \`\${y}-\${m[1].padStart(2, '0')}-\${m[2].padStart(2, '0')}\`; }
  }
  return '';
}

/** The text after "Customer:" near the top of the sheet. */
function customerFromSheet(rows) {
  for (const r of rows.slice(0, 6)) {
    const i = r.findIndex(c => /^customer:?$/i.test(txt(c)));
    if (i >= 0) return txt(r.slice(i + 1).find(c => txt(c)));
  }
  return '';
}

/** Match the file's customer ("DOMTAR 6021", "IPG - ITAPE", …) to the throughput customers. */
export function matchCustomers(fileName, list) {
  const clean = s => key(String(s).replace(/\\b60(21|49)\\b/g, ''));
  const hit = name => list.filter(c => namesOf(c).some(n => clean(n) && clean(name) === clean(n)));
  let found = hit(fileName.customer);
  if (!found.length) found = list.filter(c => namesOf(c).some(n => clean(n).length > 2 && clean(fileName.customer).startsWith(clean(n))));
  if (!found.length) found = list.filter(c => namesOf(c).some(n => clean(n).length > 2 && key(fileName.file).includes(clean(n))));
  // A customer can be in both buildings (Nexus): keep one entry per building, first match wins.
  const seen = new Set();
  return found.filter(c => !seen.has(String(c.building)) && seen.add(String(c.building)));
}

/** A quick look at any spreadsheet / CSV: each sheet's row count and its first few non-blank rows. */
export async function previewFile(file, take = 6) {
  const XLSX = await import(SHEETJS);
  const wb = XLSX.read(await file.arrayBuffer());
  return { file: file.name, sheets: wb.SheetNames.map(name => {
    const rows = XLSX.utils.sheet_to_json(wb.Sheets[name], { header: 1, raw: false, defval: '' }).filter(r => r.some(c => txt(c)));
    const width = Math.min(12, Math.max(0, ...rows.slice(0, take).map(r => r.length)));
    return { name, count: rows.length, head: rows.slice(0, take).map(r => Array.from({ length: width }, (_, i) => txt(r[i]))) };
  }) };
}

/** Read one workbook → { file, customer, week, loads: [{dir, building, date, bl, skids, tons, mt}], billing: {pallets, bundles}, skipped: [text] } */
export async function readBillingFile(file) {
  const XLSX = await import(SHEETJS);
  const wb = XLSX.read(await file.arrayBuffer());
  const out = { file: file.name, customer: '', week: '', loads: [], billing: {}, skipped: [] };
  for (const name of wb.SheetNames) {
    const rows = XLSX.utils.sheet_to_json(wb.Sheets[name], { header: 1, raw: true, defval: '' });
    // Billing sheet (IPG): "Initial Storage per Pallet / Bundle" with a "Total QTY" column.
    const qh = rows.findIndex(r => r.some(c => /^total\\s*qty$/i.test(txt(c))));
    if (qh >= 0) {
      const qc = rows[qh].findIndex(c => /^total\\s*qty$/i.test(txt(c)));
      for (const r of rows.slice(qh + 1)) {
        const label = txt(r.find(c => txt(c)));
        const m = label.match(/^initial storage per (pallet|bundle)/i);
        if (m) out.billing[m[1].toLowerCase() === 'pallet' ? 'pallets' : 'bundles'] = num(r[qc]);
      }
    }
    // Activity sheet: header row with "In/Out".
    const h = rows.findIndex(r => r.some(c => /^in\\s*\\/\\s*out$/i.test(txt(c))));
    if (h < 0) continue;
    out.week ||= weekFromTitle(rows);
    out.customer ||= customerFromSheet(rows);
    const head = rows[h].map(c => norm(c));
    const col = (...names) => head.findIndex(c => names.some(n => c === n));
    const ci = col('IN/OUT'), cs = col('SKIDS'), cn = col('NOTE'), cp = col('PO NUMBER', 'PO #', 'PO'), cd = col('DATE'), cb = col('BL #', 'BL', 'BOL #', 'BOL');
    const cwh = col('WEIGHT (LBS)', 'WEIGHT'), cw = cwh >= 0 ? cwh : COL_O;
    for (const r of rows.slice(h + 1)) {
      const dir = norm(r[ci]);
      if (dir !== 'IN' && dir !== 'OUT') continue;
      // Purge / DNB / Do not Bill in the PO Number or Note: not throughput.
      const flag = [cp, cn].filter(i => i >= 0).map(i => txt(r[i])).find(v => NOT_THROUGHPUT.test(v));
      if (flag) { out.skipped.push(\`\${dir === 'IN' ? 'In' : 'Out'} · \${flag}\`); continue; }
      const lbs = num(r[cw]);
      const bldg = cn >= 0 ? (txt(r[cn]).match(/^(6021|6049)$/) || [])[1] || '' : '';
      out.loads.push({
        dir: dir === 'IN' ? 'In' : 'Out', building: bldg,
        date: cd >= 0 ? excelDate(r[cd]) : '', bl: cb >= 0 ? txt(r[cb]) : '',
        skids: cs >= 0 ? num(r[cs]) : 0, tons: lbs / LBS_PER_TON, mt: lbs / LBS_PER_MT,
      });
    }
  }
  if (!out.loads.length && !Object.keys(out.billing).length) throw new Error(\`\${file.name}: no "In/Out" activity table found.\`);
  return out;
}

/**
 * Turn a read file into Weekly Entry values for each matching customer:
 * [{ c, values: { Pallets: {in, out}, Tons: {...}, MT: {...}, Bundles: {...} }, loads, shipped: {out, prev, in, inPrev} }]
 * shipped.out / in = loads shipped / received that week; prev / inPrev = how many of them are dated in the previous month.
 */
export function toThroughput(parsed, customers) {
  const matches = matchCustomers(parsed, customers);
  const round = (v, d) => Math.round(v * 10 ** d) / 10 ** d;
  return matches.map(c => {
    // Loads tagged with a building (Nexus) go to that building's entry; untagged loads to the only / first entry.
    const loads = parsed.loads.filter(l => (l.building ? l.building === String(c.building) : c === matches[0]));
    const sum = (dir, f) => loads.filter(l => l.dir === dir).reduce((a, l) => a + l[f], 0);
    // Weight customers' skids are rolls: their Pallets (IPG) come from the billing sheet, not the Skids column.
    const units = unitsOf(c), rollsNotPallets = units.includes('Tons');
    const values = {};
    for (const u of units) {
      if (u === 'Pallets' && rollsNotPallets) values[u] = { in: num(parsed.billing.pallets), out: '' };
      else if (u === 'Bundles') values[u] = { in: num(parsed.billing.bundles), out: '' };
      else if (u === 'Pallets') values[u] = { in: sum('In', 'skids'), out: sum('Out', 'skids') };
      else if (u === 'Tons') values[u] = { in: round(sum('In', 'tons'), 3), out: round(sum('Out', 'tons'), 3) };
      else if (u === 'MT') values[u] = { in: round(sum('In', 'mt'), 3), out: round(sum('Out', 'mt'), 3) };
    }
    // Loads: one per BL # (or per line when there is no BL #); prev = those dated in the month before the week ending's.
    const monthStart = parsed.week ? parsed.week.slice(0, 8) + '01' : '';
    const count = dir => {
      const bls = new Map();
      for (const l of loads.filter(l => l.dir === dir)) bls.set(l.bl || bls.size + '#', l);
      return { n: bls.size, prev: [...bls.values()].filter(l => monthStart && /^\\d{4}-\\d\\d-\\d\\d$/.test(l.date) && l.date < monthStart).length };
    };
    const o = count('Out'), i = count('In');
    return { c, values, loads: loads.length, shipped: { out: o.n, prev: o.prev, in: i.n, inPrev: i.prev } };
  });
}`]);

