  // ☐ / ☒ boxes have no font of their own in these templates, so Word substitutes one that draws them as tiny
  // asterisks. Put every box in its own run in Segoe UI Symbol (on every Windows PC) so they show as real boxes.
  for (const t of all(doc, 't').filter(x => /[☐☒]/.test(x.textContent))) {
    const r = t.parentNode, rPr = all(r, 'rPr')[0];
    for (const piece of t.textContent.split(/([☐☒])/).filter(Boolean)) {
      const nr = el('r'), nt = el('t'), pr = rPr ? rPr.cloneNode(true) : el('rPr');
      if (/^[☐☒]$/.test(piece)) { for (const old of all(pr, 'rFonts')) old.remove(); pr.prepend(el('rFonts', { ascii: 'Segoe UI Symbol', hAnsi: 'Segoe UI Symbol', eastAsia: 'Segoe UI Symbol', cs: 'Segoe UI Symbol' })); }
      nt.setAttributeNS(XML_NS, 'xml:space', 'preserve'); nt.textContent = piece; nr.append(pr, nt); r.parentNode.insertBefore(nr, r);
    }
    r.remove();
  }
