    if (names.includes('Fleet Register') && !names.includes('OTIF Log')) return 'mhe';
    if (names.includes('OTIF Log') || names.includes('Settings')) return 'kpi';
    const head = XLSX.utils.sheet_to_csv(wb.Sheets[names[0]]).toUpperCase();
