    const img = await createImageBitmap(await (await fetch(dataUrl)).blob()), k = Math.min(1, 240 / Math.max(img.width, img.height));
    const c = document.createElement('canvas'); c.width = Math.round(img.width * k); c.height = Math.round(img.height * k);
