ATL_SRC.push(['@atl/views/monthly.js', 0, `// Monthly Inputs: loads shipped + headcount per building (feeds Order Accuracy % and Attendance Rate).
// Nothing here is typed any more except Notes (and fixing an earlier month's saved headcount):
//  - Loads shipped add up from the weekly Customer Throughput (calc.js ▸ loadsShipped) and the month closes once its
//    last week is posted.
//  - Headcount is the active roster for the building (calc.js ▸ headcount): live for the current month, saved for past ones.
import { store } from '@atl/store.js';
import { esc, fmtDate, fmtMonth, fmtNum, monthStart, todayISO, toast, $$ } from '@atl/util.js';
import { section, kpi, chart, chartBox } from '@atl/ui.js';
import { headcount, loadsShipped, loadsIn } from '@atl/calc.js';

const BLDGS = ['6049', '6021'];
// Loads In (received) shows beside Loads Shipped; both add up from the posted Billing Activity files. Only loads shipped
// and headcount count toward a month being complete (they feed the KPIs).
const COLS = [['in', 'Loads In'], ['loads', 'Loads Shipped'], ['hc', 'Headcount']];
/** A month's value as shown for column k ('loads' | 'hc') and building b. */
const shown = (mk, k, b) => (k === 'hc' ? headcount(mk, b) : k === 'in' ? loadsIn(mk, b).value : loadsShipped(mk, b).value);
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
let year = null;

const monthsFor = y => Array.from({ length: 12 }, (_, i) => {
  const mk = \`\${y}-\${String(i + 1).padStart(2, '0')}\`;
  const d = store.rows('monthly').find(m => m.id === mk) || {};
  // Complete = loads shipped and headcount for both buildings.
  const filled = BLDGS.flatMap(b => ['loads', 'hc'].map(k => shown(mk, k, b))).filter(v => typeof v === 'number').length;
  const ld = loadsShipped(mk, 'all');
  return { i, mk, d, complete: filled === 4 && (!ld.auto || ld.closed), any: filled > 0, filled, auto: ld.auto, closed: ld.closed, through: ld.through, missing: ld.missing };
});

export default {
  needs: () => ['monthly', 'employees', 'throughput'],
  render() {
    const y = year || store.settings.reportingYear;
    const can = store.can('edit');
    const months = monthsFor(y);
    // Months that should be in by now: every month before the current one (in the current year), or all 12 for past years.
    const now = new Date(), due = y < now.getFullYear() ? 12 : y > now.getFullYear() ? 0 : now.getMonth();
    const complete = months.filter(m => m.complete).length, partial = months.filter(m => m.any && !m.complete).length;
    const missingDue = months.slice(0, due).filter(m => !m.complete).map(m => MON[m.i]);
    const total = (k, b) => months.reduce((a, m) => a + (typeof shown(m.mk, k, b) === 'number' ? shown(m.mk, k, b) : 0), 0);
    const tiles = [
      kpi('Months complete', \`\${complete} <small>/ 12</small>\`, \`\${partial} partial\`, complete >= due && due ? 'good' : ''),
      kpi('Closed months still missing', fmtNum(missingDue.length), missingDue.length ? esc(missingDue.join(', ')) : due ? 'All closed months in' : 'No months closed yet', missingDue.length ? 'bad' : 'good'),
      kpi(\`Loads in — \${y}\`, fmtNum(total('in', '6049') + total('in', '6021')), \`6049: \${fmtNum(total('in', '6049'))}&nbsp; | &nbsp;6021: \${fmtNum(total('in', '6021'))}\`),
      kpi(\`Loads shipped — \${y}\`, fmtNum(total('loads', '6049') + total('loads', '6021')), \`6049: \${fmtNum(total('loads', '6049'))}&nbsp; | &nbsp;6021: \${fmtNum(total('loads', '6021'))}\`),
    ];
    // Only an earlier month's saved headcount can be fixed by hand; everything else is filled in by the app.
    const cur = todayISO().slice(0, 7);
    const cell = (k, b, i, mk) => {
      const v = shown(mk, k, b), label = \`\${b} \${COLS.find(c => c[0] === k)[1]}, \${MON[i]} \${y}\`;
      if (k === 'hc' && mk < cur) return \`<input type="number" step="any" min="0" data-k="hc\${b}" value="\${v ?? ''}" aria-label="\${label}" \${can ? '' : 'disabled'}>\`;
      const tip = k === 'hc' ? 'Active people on the roster with this Home Facility' : k === 'in' ? 'Inbound loads from the weekly Customer Throughput' : 'Outbound loads from the weekly Customer Throughput';
      return \`<span class="mi-ro" title="\${tip}" aria-label="\${label}">\${typeof v === 'number' ? fmtNum(v) : '—'}</span>\`;
    };
    const status = m => m.auto && m.closed ? '<span class="mi-st ok">✓ Closed</span>'
      : m.auto && m.missing.length ? \`<span class="mi-st miss" title="Post these weeks' Customer Throughput (with loads) on Weekly Entry">⚠ No loads for wk \${m.missing.map(fmtDate).join(', ')}</span>\`
      : m.auto ? \`<span class="mi-st part" title="Adds up as each week's throughput is posted; closes after the month's last week">In progress\${m.through ? \` · thru wk \${fmtDate(m.through)}\` : ''}</span>\`
      : m.complete ? '<span class="mi-st ok">✓ Complete</span>' : m.any ? \`<span class="mi-st part">Partial · \${m.filled}/4</span>\` : m.i < due ? '<span class="mi-st miss">Missing</span>' : '<span class="mi-st">—</span>';
    const rows = months.map(m => \`<tr data-mk="\${m.mk}" class="\${m.i < due && !m.complete ? 'due' : ''}">
        <td class="mon">\${fmtMonth(monthStart(y, m.i + 1))}</td>
        \${BLDGS.map(b => COLS.map(([k], ci) => \`<td class="num\${ci ? '' : ' b1'}">\${cell(k, b, m.i, m.mk)}</td>\`).join('')).join('')}
        <td class="b1 nowrap">\${status(m)}</td>
        <td class="note-cell"><input type="text" data-k="notes" value="\${esc(m.d.notes ?? '')}" aria-label="Notes, \${MON[m.i]} \${y}" \${can ? '' : 'disabled'}></td></tr>\`).join('');
    const yearSel = \`<label class="xl-chg">Year <select data-y aria-label="Year">\${[y - 2, y - 1, y, y + 1].map(v => \`<option \${v === y ? 'selected' : ''}>\${v}</option>\`).join('')}</select></label>\`;
    return \`<div class="log-xl mi-xl">
      <div class="xl-dash-head log-head">
        <div class="xl-banner"><h1>PIPER WAREHOUSE&nbsp; | &nbsp;Monthly Inputs</h1>
          <p>Filled in by the app. Loads in and loads shipped add up from each week's Customer Throughput (Billing Activity files on Weekly Entry) and feed Order Accuracy %; a month closes after its last week is posted. Headcount is the Active people on the roster by Home Facility and feeds Attendance Rate.</p></div>
        <div class="xl-meta"><b>Year:</b><span class="xl-year">\${y}</span><b>Months complete</b><span class="xl-thru">\${complete} of 12</span>\${yearSel}</div>
        <div class="log-insights"><div class="xl-tiles q" style="grid-template-columns:repeat(\${tiles.length}, minmax(0, 1fr))">\${tiles.join('')}</div>
          <div class="log-chart"><div class="xl-chart"><h4>Loads shipped &amp; headcount by month — \${y}</h4>\${chartBox('ch-mi', 260, \`Loads shipped per month for 6049 and 6021, with headcount lines, \${y}\`)}</div></div></div>
      </div>\` +
      section(\`\${y} — By Month\`, \`<div class="table-wrap"><table class="grid entry mi-table"><thead>
        <tr><th rowspan="2">Month</th>\${BLDGS.map(b => \`<th colspan="\${COLS.length}" class="grp">Building \${b}</th>\`).join('')}<th rowspan="2">Status</th><th rowspan="2">Notes</th></tr>
        <tr>\${BLDGS.map(() => COLS.map(([, l]) => \`<th class="num">\${l}</th>\`).join('')).join('')}</tr></thead><tbody>\${rows}</tbody></table></div>
        <p class="xl-foot">Loads come from Weekly Entry ▸ Customer Throughput: each Out line in a Billing Activity file is one load shipped (one per BL #; Purge / DNB / Do not Bill lines left out). A week that runs into the next month splits by the load's date. Months before the weekly loads started show the workbook's numbers. This month's headcount follows the Employees roster and is saved into the month, so past months keep the headcount they had. Rows tinted red are closed months that are still missing numbers.</p>\`) + '</div>';
  },
  after(root, p, rerender) {
    $$('[data-y]', root).forEach(s => s.addEventListener('change', e => { year = +e.target.value; rerender(); }));
    $$('tr[data-mk] input', root).forEach(inp => inp.addEventListener('change', async e => {
      const mk = e.target.closest('tr').dataset.mk, k = e.target.dataset.k;
      const v = k === 'notes' ? e.target.value : e.target.value === '' ? null : +e.target.value;
      const rest = { ...(store.rows('monthly').find(m => m.id === mk) || {}) };
      delete rest.id;
      try { await store.set('monthly', mk, { ...rest, month: mk + '-01', [k]: v }); toast('Saved'); } catch (err) { toast(err.message, 'bad'); }
    }));
    // Loads shipped (bars, left axis) and headcount (lines, right axis) by building.
    const y = year || store.settings.reportingYear, months = monthsFor(y), v = (k, b) => months.map(m => {
      const x = shown(m.mk, k, b);
      return typeof x === 'number' ? x : null;
    });
    chart('ch-mi', {
      data: { labels: MON, datasets: [
        { type: 'line', label: '6049 headcount', data: v('hc', '6049'), borderColor: '#222b36', backgroundColor: '#222b36', pointBackgroundColor: '#fff', pointRadius: 3, borderWidth: 2, yAxisID: 'y1', order: 0, spanGaps: true },
        { type: 'line', label: '6021 headcount', data: v('hc', '6021'), borderColor: '#c0392b', backgroundColor: '#c0392b', pointBackgroundColor: '#fff', pointRadius: 3, borderWidth: 2, borderDash: [5, 3], yAxisID: 'y1', order: 0, spanGaps: true },
        { type: 'bar', label: '6049 loads shipped', data: v('loads', '6049'), backgroundColor: '#4d6f99', yAxisID: 'y', order: 1, borderRadius: 2 },
        { type: 'bar', label: '6021 loads shipped', data: v('loads', '6021'), backgroundColor: '#c0904d', yAxisID: 'y', order: 1, borderRadius: 2 },
      ] },
      options: { interaction: { mode: 'index', intersect: false }, plugins: { legend: { position: 'bottom', labels: { boxWidth: 12, padding: 14 } } },
        scales: { x: { grid: { display: false } }, y: { beginAtZero: true, title: { display: true, text: 'Loads shipped' }, ticks: { callback: n => n.toLocaleString() } },
          y1: { position: 'right', beginAtZero: true, grid: { display: false }, title: { display: true, text: 'Headcount' } } } },
    });
  },
};`]);

