ATL_SRC.push(['@atl/views/writeup.js', 0, `// Write-up dialog (Disciplinary Log ▸ New write-up): fill in the Employee Corrective Action / Write-Up form in the app,
// save it to the Disciplinary Log, and create an Outlook email with the filled-in Word form attached.
import { store } from '@atl/store.js';
import { derive, managerOf } from '@atl/calc.js';
import { esc, fmtDate, norm, toast, downloadBlob } from '@atl/util.js';
import { writeUpDocx, writeUpFileName, LEVELS, VIOLATIONS, LEVEL_TO_ACTION, VIOLATION_TO_CATEGORY } from '@atl/forms/writeup.js';
import { emlDraft } from '@atl/forms/email.js';
import { archiveSent, employeeBuilding } from '@atl/forms/archive.js';
import { DOCX } from '@atl/forms/docx.js';
import { suggestSOPs, allSOPRules, allSOPDocs, sopCitation, sopTag } from '@atl/forms/sopmatch.js';

const todayISO = () => { const d = new Date(); return \`\${d.getFullYear()}-\${String(d.getMonth() + 1).padStart(2, '0')}-\${String(d.getDate()).padStart(2, '0')}\`; };
const us = iso => (iso ? \`\${+iso.slice(5, 7)}/\${+iso.slice(8, 10)}/\${iso.slice(0, 4)}\` : '');
const empByName = name => store.rows('employees').find(e => e.name && norm(e.name) === norm(name));
/** Earlier write-ups for this employee from the Disciplinary Log, newest first: "1/15/2026 – Written Warning (Active)". */
const priorFor = (name, before) => derive('discipline').filter(r => norm(r.employee) === norm(name) && r.date && r.date < before)
  .sort((a, b) => b.date.localeCompare(a.date)).map(r => \`\${us(r.date)} – \${r.action || 'Action'}\${r.status ? \` (\${r.status})\` : ''}\`);

/** Open the write-up dialog. rerender: redraw the Disciplinary Log after saving. */
export function openWriteUp(rerender) {
  const emps = store.rows('employees').filter(e => e.name);
  const active = emps.filter(e => norm(e.rosterStatus) === 'ACTIVE').sort((a, b) => a.name.localeCompare(b.name));
  const former = emps.filter(e => norm(e.rosterStatus) !== 'ACTIVE').sort((a, b) => a.name.localeCompare(b.name));
  const opt = e => \`<option value="\${esc(e.name)}">\${esc(e.name)}</option>\`;
  document.querySelector('.wu-back')?.remove();
  const el = document.createElement('div');
  el.className = 'modal-back wu-back';
  el.innerHTML = \`<form class="modal wu-pop" novalidate role="dialog" aria-modal="true" aria-labelledby="wu-title">
    <div class="modal-head"><h2 id="wu-title">✎ Employee corrective action / write-up</h2><button type="button" class="icon-btn" data-close aria-label="Close">✕</button></div>
    <p class="muted small">Fills in the company Write-Up form. Employee Comments and the signatures are left blank for the meeting with the employee. Confidential — managers &amp; HR only.</p>

    <fieldset class="wu-sec"><legend>Employee information</legend><div class="wu-grid">
      <label class="wide">Employee name <select name="name" required><option value="">— choose —</option><optgroup label="Active roster">\${active.map(opt).join('')}</optgroup>\${former.length ? \`<optgroup label="Not on current roster">\${former.map(opt).join('')}</optgroup>\` : ''}</select></label>
      <label>Employee ID <input name="employeeId" type="text"></label>
      <label>Job title <input name="jobTitle" type="text" placeholder="e.g. Warehouse Associate"></label>
      <label>Shift <select name="shift"><option>First</option><option>Second</option><option>Third</option></select></label>
      <label>Facility / location <input name="facility" type="text"></label>
      <label>Supervisor / manager <input name="manager" type="text"></label>
      <label>Date of write-up <input name="date" type="date" value="\${todayISO()}" required></label>
      <label>Date of incident <input name="incidentDate" type="date"></label>
      <label>Time of incident <input name="incidentTime" type="time"></label>
    </div></fieldset>

    <fieldset class="wu-sec"><legend>Level of corrective action <small>(check one)</small></legend>
      <div class="wu-chips" role="radiogroup">\${LEVELS.map((l, i) => \`<label><input type="radio" name="level" value="\${l}"\${i ? '' : ' checked'}> \${l}</label>\`).join('')}
        <label class="wu-days" hidden>Days <input name="suspensionDays" type="number" min="0.5" step="0.5" value="1"></label></div></fieldset>

    <fieldset class="wu-sec"><legend>Type of violation <small>(check all that apply)</small></legend>
      <div class="wu-chips">\${VIOLATIONS.map(v => \`<label><input type="checkbox" name="violations" value="\${v}"> \${v}</label>\`).join('')}</div>
      <label class="wu-other" hidden>Other — describe <input name="otherViolation" type="text"></label></fieldset>

    <fieldset class="wu-sec"><legend>Incident summary</legend>
      <textarea name="summary" rows="5" required placeholder="What happened — who, what, when, where. Stick to facts."></textarea></fieldset>

    <fieldset class="wu-sec"><legend>Policy / procedure violated &amp; prior corrective actions</legend><div class="wu-grid">
      <label class="wide">Suggested SOP / policy violated <span class="muted small" data-sop-hint>— write the incident summary above and matching SOP rules appear here</span>
        <select name="sopPick" aria-describedby="wu-sop-help"><option value="">— choose an SOP rule to add —</option></select></label>
      <label class="wide">Policy / SOP violated <textarea name="policy" rows="3" placeholder="Choose from the list above, or type a handbook section / SOP number and title"></textarea></label>
      <p class="wide muted small" id="wu-sop-help">Suggestions come from the Employee Handbook, the safety and operating SOPs, the SQF food-safety program (GMP, allergens, pest control, sanitation, food defense…) and the building placards — everything in SOP/Documents — matched to the incident summary. Each one you choose is added on its own line; edit freely.</p>
      <div class="wide wu-prior"><span>Prior related actions</span>
        <label><input type="radio" name="prior" value="None" checked> None</label><label><input type="radio" name="prior" value="Yes"> Yes</label>
        <input name="priorText" type="text" placeholder="Date(s) / level" aria-label="Prior actions — dates and levels"></div>
      <p class="wide muted small wu-prior-note" data-prior-note></p></div></fieldset>

    <fieldset class="wu-sec"><legend>Disciplinary action &amp; expected improvement</legend>
      <textarea name="action" rows="3" placeholder="The action taken and what must change going forward."></textarea></fieldset>

    <div class="modal-foot"><div class="wu-opts">
        <label><input type="checkbox" name="save" checked> Save to the Disciplinary Log</label>
        <label><input type="checkbox" name="email" checked> Create an <b>Outlook email</b> with the write-up attached</label></div>
      <div><button type="button" class="btn ghost" data-close>Cancel</button><button type="submit" class="btn primary">Create write-up</button></div></div>
  </form>\`;
  document.body.appendChild(el);
  const form = el.querySelector('form'), f = form.elements;
  const close = () => el.remove();
  el.addEventListener('click', e => { if (e.target === el || e.target.closest('[data-close]')) close(); });
  el.addEventListener('keydown', e => { if (e.key === 'Escape') close(); });

  // Choosing the employee fills in ID, facility, manager and their earlier write-ups from the Disciplinary Log.
  const fillFromEmployee = () => {
    const e = empByName(f.name.value); if (!e) return;
    f.employeeId.value = e.hrId || '';
    f.employeeId.placeholder = e.hrId ? '' : 'Not on file yet — saved at the next HR timesheet import';
    f.facility.value = e.homeFacility || e.defaultBuilding || '';
    f.manager.value = managerOf(e);
    const prior = priorFor(e.name, f.date.value || todayISO());
    form.querySelector(\`[name="prior"][value="\${prior.length ? 'Yes' : 'None'}"]\`).checked = true;
    f.priorText.value = prior.join('; ');
    form.querySelector('[data-prior-note]').textContent = prior.length ? \`Found \${prior.length} earlier entr\${prior.length === 1 ? 'y' : 'ies'} in the Disciplinary Log — edit if needed.\` : 'No earlier entries in the Disciplinary Log.';
  };
  // SOP drop-down: best matches for the incident summary (and violation types) first, then every rule by document.
  const rules = allSOPRules();
  const ruleOpt = (r, tag = '') => \`<option value="\${r.i}">\${esc(\`\${tag}\${sopTag(r.doc)} · \${r.section} — \${r.text}\`.slice(0, 190))}</option>\`;
  const fullList = allSOPDocs().map((doc, d) => \`<optgroup label="All rules — \${esc([doc.number, doc.short || doc.title].filter(Boolean).join(' '))}">\${rules.filter(r => r.d === d).map(r => ruleOpt(r)).join('')}</optgroup>\`).join('');
  const refreshSOPs = () => {
    const text = [f.summary.value, ...[...form.querySelectorAll('[name="violations"]:checked')].map(c => c.value), f.otherViolation.value].join(' ');
    const hits = suggestSOPs(text, 8), hint = form.querySelector('[data-sop-hint]');
    f.sopPick.innerHTML = \`<option value="">\${hits.length ? \`— \${hits.length} suggested rule\${hits.length === 1 ? '' : 's'} — choose one to add —\` : '— choose an SOP rule to add —'}</option>\`
      + (hits.length ? \`<optgroup label="Suggested from the incident summary (best match first)">\${hits.map(h => ruleOpt(h.rule, h.score > 4 ? '★ ' : '')).join('')}</optgroup>\` : '') + fullList;
    hint.textContent = !f.summary.value.trim() ? '— write the incident summary above and matching SOP rules appear here'
      : hits.length ? \`— \${hits.length} suggestion\${hits.length === 1 ? '' : 's'} from the summary (★ = strong match)\` : '— no close match in the SOPs; choose from the full list or type it in';
  };
  let sopTimer;
  f.summary.addEventListener('input', () => { clearTimeout(sopTimer); sopTimer = setTimeout(refreshSOPs, 300); });
  f.sopPick.addEventListener('change', () => {
    const r = rules[+f.sopPick.value]; if (!r) return;
    const line = sopCitation(r), cur = f.policy.value.trim();
    if (!cur.split('\\n').includes(line)) f.policy.value = cur ? \`\${cur}\\n\${line}\` : line;
    f.sopPick.value = '';
    f.policy.style.height = 'auto'; f.policy.style.height = Math.min(220, f.policy.scrollHeight + 4) + 'px'; // grow to show every line
  });
  refreshSOPs();

  form.addEventListener('change', e => {
    if (e.target.name === 'name' || e.target.name === 'date') fillFromEmployee();
    if (e.target.name === 'violations' || e.target.name === 'otherViolation') refreshSOPs();
    form.querySelector('.wu-days').hidden = form.querySelector('[name="level"]:checked')?.value !== 'Suspension';
    form.querySelector('.wu-other').hidden = !form.querySelector('[name="violations"][value="Other"]').checked;
  });

  form.addEventListener('submit', async e => {
    e.preventDefault();
    const w = {
      name: f.name.value, employeeId: f.employeeId.value.trim(), jobTitle: f.jobTitle.value.trim(), shift: f.shift.value,
      facility: f.facility.value.trim(), manager: f.manager.value.trim(), date: f.date.value, incidentDate: f.incidentDate.value, incidentTime: f.incidentTime.value,
      level: form.querySelector('[name="level"]:checked')?.value, suspensionDays: f.suspensionDays.value,
      violations: [...form.querySelectorAll('[name="violations"]:checked')].map(c => c.value), otherViolation: f.otherViolation.value.trim(),
      summary: f.summary.value.trim(), policy: f.policy.value.trim(), prior: form.querySelector('[name="prior"]:checked')?.value,
      priorText: f.priorText.value.trim(), action: f.action.value.trim(),
    };
    const missing = [!w.name && 'Employee name', !w.date && 'Date of write-up', !w.summary && 'Incident summary', !w.violations.length && 'Type of violation'].filter(Boolean);
    if (missing.length) { toast('Required: ' + missing.join(', '), 'bad'); return; }
    const btn = form.querySelector('[type=submit]'); btn.disabled = true; btn.textContent = 'Creating…';
    try {
      if (f.save.checked) {
        // One Disciplinary Log entry; the first violation type sets its Category.
        w.refId = await store.add('discipline', {
          date: w.date, employee: w.name, category: VIOLATION_TO_CATEGORY[w.violations[0]] || 'Other', action: LEVEL_TO_ACTION[w.level] || w.level,
          description: w.summary, issuedBy: w.manager, signed: 'N',
          notes: [w.action, w.policy && \`Policy / SOP: \${w.policy}\`, w.level === 'Suspension' && \`Suspension: \${w.suspensionDays} day(s)\`, \`Violation: \${w.violations.map(v => (v === 'Other' ? \`Other – \${w.otherViolation}\` : v)).join(', ')}\`].filter(Boolean).join('\\n'),
        });
      }
      const doc = writeUpDocx(w), file = writeUpFileName(w);
      if (f.email.checked) {
        const td = 'style="border:1px solid #c8ced8;padding:4px 8px"', th = 'style="border:1px solid #c8ced8;padding:4px 8px;background:#222b36;color:#fff;text-align:left"';
        const html = \`<div style="font-family:Calibri,Arial,sans-serif;font-size:11pt"><p>Attached is the Employee Corrective Action / Write-Up for \${esc(w.name)}.</p>
          <table style="border-collapse:collapse;font-size:10pt">
          <tr><th \${th}>Employee</th><td \${td}>\${esc(w.name)}</td></tr><tr><th \${th}>Date of write-up</th><td \${td}>\${fmtDate(w.date)}</td></tr>
          <tr><th \${th}>Level</th><td \${td}>\${esc(w.level === 'Suspension' ? \`Suspension – \${w.suspensionDays} day(s)\` : w.level)}</td></tr>
          <tr><th \${th}>Violation</th><td \${td}>\${esc(w.violations.map(v => (v === 'Other' ? \`Other – \${w.otherViolation}\` : v)).join(', '))}</td></tr>
          <tr><th \${th}>Supervisor / manager</th><td \${td}>\${esc(w.manager)}</td></tr>\${w.refId ? \`<tr><th \${th}>Disciplinary Log</th><td \${td}>\${esc(w.refId)}</td></tr>\` : ''}</table>
          <p style="color:#5b6478;font-size:9pt">Confidential — for management and HR only. Created in the Piper Warehouse Operations Dashboard.</p></div>\`;
        const subject = \`Employee Write-Up – \${w.name} – \${us(w.date)}\`;
        const attachments = [[file, new Uint8Array(await doc.arrayBuffer()), DOCX]];
        downloadBlob(\`\${subject.replace(/\\//g, '-')}.eml\`, emlDraft({ subject, html, attachments }));
        await archiveSent({ kind: 'writeup', building: employeeBuilding(w.name), fileDate: w.date, title: \`\${w.name} – \${w.level === 'Suspension' ? \`Suspension (\${w.suspensionDays} day(s))\` : w.level || 'Write-up'}\`, subject, html, attachments, ref: w.refId || \`\${w.name}-\${w.date}\` });
      } else {
        downloadBlob(file, doc);
        await archiveSent({ kind: 'writeup', building: employeeBuilding(w.name), fileDate: w.date, title: \`\${w.name} – \${w.level === 'Suspension' ? \`Suspension (\${w.suspensionDays} day(s))\` : w.level || 'Write-up'}\`, subject: file.replace(/\\.docx$/, ''), html: '', attachments: [[file, new Uint8Array(await doc.arrayBuffer()), DOCX]], ref: w.refId || \`\${w.name}-\${w.date}\` });
      }
      close(); rerender?.();
      toast(\`\${f.save.checked ? \`Write-up saved to the Disciplinary Log\${w.refId ? \` (\${w.refId})\` : ''}. \` : ''}\${f.email.checked ? 'Outlook email created — open the .eml file to review and send.' : 'Word form downloaded.'}\`);
    } catch (err) { console.error(err); toast(err.message, 'bad'); btn.disabled = false; btn.textContent = 'Create write-up'; }
  });
  setTimeout(() => f.name.focus(), 30);
}`]);
